<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        if (Array.isArray(current)) {
            if (current.length > 0) {
                 const actualValue = current[0];
                 if (typeof actualValue === 'boolean') {
                     return actualValue;
                 }
                 return String(actualValue);
            } else {
                return defaultValue;
            }
        }
        if (typeof current === 'boolean') {
            return current;
        }
        return String(current);
    }

    function updateProgressBar(barContainerId, valueMainId, valueDescId, rawValueFromCharacterData, min, max) {
        const barContainer = document.getElementById(barContainerId);
        const progressBar = barContainer ? barContainer.querySelector('.progress-bar-value') : null;
        const valueMainDisplay = document.getElementById(valueMainId);
        const valueDescDisplay = document.getElementById(valueDescId);

        if (!valueMainDisplay) {
            return;
        }

        let numericValue = min;
        let descriptionText = "";

        if (Array.isArray(rawValueFromCharacterData) && rawValueFromCharacterData.length > 1 && typeof rawValueFromCharacterData[1] === 'string') {
            descriptionText = rawValueFromCharacterData[1];
        }

        const valueToParse = Array.isArray(rawValueFromCharacterData) ? rawValueFromCharacterData[0] : rawValueFromCharacterData;

        if (String(valueToParse).match(/^(-?\d+(\.\d+)?)$/) && isFinite(parseFloat(valueToParse))) {
            numericValue = parseFloat(valueToParse);
            valueMainDisplay.innerText = String(numericValue);
        } else {
            valueMainDisplay.innerText = SafeGetValue({temp: valueToParse}, 'temp', String(min));
        }


        if (valueDescDisplay) {
             valueDescDisplay.innerText = descriptionText ? `(${descriptionText.split('。')[0]})` : "";
        }

        if (progressBar) {
            numericValue = Math.max(min, Math.min(max, numericValue));
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
        }
    }

    function triggerSillyTavernCommand(message) {
        if (typeof parent.sendForm === 'function') {
            parent.sendForm({ text: message });
        } else if (typeof triggerSlash === 'function') {
            const escapedMessage = message.replace(/`/g, '\\`').replace(/'/g, "\\'").replace(/"/g, '\\"');
            triggerSlash(`/send ${escapedMessage}|/trigger`);
        } else {
            console.error('Error: Could not send message. Parent sendForm or triggerSlash not found.');
            alert('无法发送指令。请确保在SillyTavern环境中运行。');
        }
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<div class='card-overlay'><p style='color:red; padding:10px;'>无法加载状态数据 (messages empty)</p></div>";
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.stat_data;
            if (!characterData) {
                 document.getElementById('status-card').innerHTML = "<div class='card-overlay'><p style='color:red; padding:10px;'>无法加载状态数据 (stat_data missing)</p></div>";
                 return;
            }

            const dateTimeElement = document.getElementById('world-datetime');
            if (dateTimeElement) {
                 const dateValue = SafeGetValue(characterData, '日期', '01月01日');
                 const timeValue = SafeGetValue(characterData, '时间', '清晨');
                 dateTimeElement.innerText = dateValue && timeValue ? `${dateValue} ${timeValue}` : '01月01日 清晨';
            }

            const characterKey = "梦星曦";

            if (characterData.hasOwnProperty(characterKey)) {
                const mengXingXiData = characterData[characterKey];

                const seseModeElement = document.getElementById('sese-mode-value');
                if (seseModeElement) {
                    seseModeElement.innerText = SafeGetValue(mengXingXiData, '瑟瑟模式', false) === true ? '开启' : '关闭';
                }

                updateProgressBar(
                    'mengxingxi-affection-bar',
                    'mengxingxi-affection',
                    'mengxingxi-affection-desc',
                    mengXingXiData.好感度,
                    0, 100
                );
                updateProgressBar(
                    'mengxingxi-anger-bar',
                    'mengxingxi-anger',
                    'mengxingxi-anger-desc',
                    mengXingXiData.生气值,
                    0, 100
                );
                updateProgressBar(
                    'mengxingxi-arousal-bar',
                    'mengxingxi-arousal',
                    'mengxingxi-arousal-desc',
                    mengXingXiData.瑟瑟感,
                    0, 100
                );
            } else {
                 const defaultText = '(角色数据缺失)';
                 const seseModeElem = document.getElementById('sese-mode-value');
                 if(seseModeElem) seseModeElem.innerText = 'N/A';

                 document.getElementById('mengxingxi-affection').innerText = 'N/A';
                 document.getElementById('mengxingxi-affection-desc').innerText = defaultText;
                 if(document.getElementById('mengxingxi-affection-bar')) document.getElementById('mengxingxi-affection-bar').querySelector('.progress-bar-value').style.width = '0%';

                 document.getElementById('mengxingxi-anger').innerText = 'N/A';
                 document.getElementById('mengxingxi-anger-desc').innerText = defaultText;
                 if(document.getElementById('mengxingxi-anger-bar')) document.getElementById('mengxingxi-anger-bar').querySelector('.progress-bar-value').style.width = '0%';

                 document.getElementById('mengxingxi-arousal').innerText = 'N/A';
                 document.getElementById('mengxingxi-arousal-desc').innerText = defaultText;
                 if(document.getElementById('mengxingxi-arousal-bar')) document.getElementById('mengxingxi-arousal-bar').querySelector('.progress-bar-value').style.width = '0%';
            }
        } catch (error) {
            document.getElementById('status-card').innerHTML = `<div class='card-overlay'><p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p></div>`;
            console.error("Error in initDisplay:", error);
        }
    }

    function toggleSection(headerElement, contentId) {
        const content = document.getElementById(contentId);
        if (!content || !headerElement) return;
        const isExpanded = content.classList.toggle('expanded');
        headerElement.classList.toggle('collapsed', !isExpanded);
        headerElement.classList.toggle('expanded', isExpanded);
        const arrow = headerElement.querySelector('.arrow-indicator');
        if (arrow) {
            arrow.innerText = isExpanded ? '▲' : '▼';
        }
    }

    document.addEventListener('DOMContentLoaded', () => {
        initDisplay();

        const btnReviseEssay = document.getElementById('btn-revise-essay');
        if (btnReviseEssay) {
            btnReviseEssay.addEventListener('click', () => {
                triggerSillyTavernCommand('根据<批改标准>中的内容，给出批改分数，指出语法错误，纠正语法错误');
            });
        }

        const btnVocabAnki = document.getElementById('btn-vocab-anki');
        if (btnVocabAnki) {
            btnVocabAnki.addEventListener('click', () => {
                triggerSillyTavernCommand('根据前文批改内容，给出我应该积累的短语，词汇，句式结构，语法知识。\n根据anki格式发送，用；格式分隔。\n使用英文正面，中文反面格式。');
            });
        }

        const arousalHeader = document.getElementById('arousal-header');
        if (arousalHeader && !arousalHeader.classList.contains('expanded')) {
            const arrow = arousalHeader.querySelector('.arrow-indicator');
            if (arrow) arrow.innerText = '▼';
            const arousalContent = document.getElementById('arousal-content');
            if (arousalContent) arousalContent.classList.remove('expanded');

        }
    });
</script>
</body>
</html>
